namespace ghidra.app.plugin.core.datapreview;

using ghidra.program.model.address;
using ghidra.program.model.data;
using ghidra.program.model.data;
using ghidra.program.model.mem;

class DataTypePreview : Preview {
	private static readonly int MAX_PREVIEW_LENGTH = 150;

	protected DataType dt;

	DataTypePreview(DataType dt) {
		this.dt = dt;
	}

	/* @Override */
	public string getName() {
		return dt.getName();
	}

	/* @Override */
	public string getPreview(Memory memory, Address addr) {
		try {
			MemBuffer mb = new DumbMemBufferImpl(memory, addr);
			DataTypeInstance dti =
				DataTypeInstance.getDataTypeInstance(dt, mb, MAX_PREVIEW_LENGTH, false);
			if (dti == null) {
				return "";
			}

			int length = Math.min(dti.getLength(), MAX_PREVIEW_LENGTH);
			return dt.getRepresentation(mb, dt.getDefaultSettings(), length);
		}
		catch (Exception e) {

			return "ERROR: unable to create preview";
		}
	}

	/* @Override */
	public DataType getDataType() {
		return dt;
	}

	/* @Override */
	public string toString() {
		return getName();
	}

	/* @Override */
	public int compareTo(Preview p) {
		if (p is DataTypePreview) {
			DataTypePreview dtp = (DataTypePreview) p;
			return getName().compareToIgnoreCase(dtp.getName());
		}
		return toString().compareToIgnoreCase(p.toString());
	}
}
